import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { normalizeFixture } from "../tooling/fixture-oracle/src/normalize.mjs";

const root = process.cwd();
const fixtureRoot = path.join(root, "contracts/fixtures");
const manifestPath = path.join(fixtureRoot, "manifest.json");
const manifest = JSON.parse(await readFile(manifestPath, "utf8"));
if (manifest.schemaVersion !== "2.0" || manifest.normalizationContract !== "ji-pi-projection-v1") {
  throw new Error("unsupported Pi fixture manifest");
}
for (const fixture of manifest.fixtures) {
  const rawPath = path.join(fixtureRoot, fixture.path);
  const expectedPath = path.join(fixtureRoot, fixture.expectedPath);
  const projection = `${JSON.stringify(await normalizeFixture(rawPath), null, 2)}\n`;
  await writeFile(expectedPath, projection);
  fixture.rawSha256 = sha256(await readFile(rawPath));
  fixture.expectedSha256 = sha256(projection);
}
await writeFile(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
process.stdout.write(`generated ${manifest.fixtures.length} Pi fixture projections\n`);

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}
